1	const PROCESSING_FEE = 5;
2	
3	export type Item = { type: string };
4	export type Step = { op: string; items?: Item[] };
5	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
6	
7	export type StepResult = { premium: number };
8	export type ScenarioResult = { results: StepResult[] };
9	
10	const BASE_PREMIUMS: Record<string, number> = {
11	  sword: 100,
12	  amulet: 60,
13	  staff: 80,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const basePremiumOf = (items: Item[]): number =>
19	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
20	
21	const quotePremium = (items: Item[]): number => {
22	  const basePremium = basePremiumOf(items);
23	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
24	  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
25	};
26	
27	export const runScenario = (scenario: Scenario): ScenarioResult => ({
28	  results: scenario.steps.map((step) => ({
29	    premium: quotePremium(step.items ?? []),
30	  })),
31	});
